/**
 * The outcome of attempting to verify a credential.
 */
sealed class Outcome {
    
    /**
     * The credential was successfully verified.
     */
    data class Verified(
        val `credentialInfo`: CredentialInfo) : Outcome() {
        companion object
    }
    
    /**
     * The credential could not be verified.
     */
    data class Unverified(
        val `credentialInfo`: CredentialInfo?, 
        val `failure`: Failure) : Outcome() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeOutcome : FfiConverterRustBuffer<Outcome>{
    override fun read(buf: ByteBuffer): Outcome {
        return when(buf.getInt()) {
            1 -> Outcome.Verified(
                FfiConverterTypeCredentialInfo.read(buf),
                )
            2 -> Outcome.Unverified(
                FfiConverterOptionalTypeCredentialInfo.read(buf),
                FfiConverterTypeFailure.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Outcome) = when(value) {
        is Outcome.Verified -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCredentialInfo.allocationSize(value.`credentialInfo`)
            )
        }
        is Outcome.Unverified -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalTypeCredentialInfo.allocationSize(value.`credentialInfo`)
                + FfiConverterTypeFailure.allocationSize(value.`failure`)
            )
        }
    }

    override fun write(value: Outcome, buf: ByteBuffer) {
        when(value) {
            is Outcome.Verified -> {
                buf.putInt(1)
                FfiConverterTypeCredentialInfo.write(value.`credentialInfo`, buf)
                Unit
            }
            is Outcome.Unverified -> {
                buf.putInt(2)
                FfiConverterOptionalTypeCredentialInfo.write(value.`credentialInfo`, buf)
                FfiConverterTypeFailure.write(value.`failure`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







